+
+// ============================================================
+// createJarvisHistory — invalid capacities throw
+// ============================================================
+
+describe("createJarvisHistory — invalid capacity throws", () => {
+  it("throws for NaN capacity", () => {
+    expect(() => createJarvisHistory(NaN)).toThrow(/positive integer/);
