+    line: -3.5,
+    confidence: 72,
+    edgeScore: 6.4,
+    consensusPct: 0.63,
+    bookmakerCount: 8,
+    dataQualityScore: 88,
+    tier: "FREE",
+    pickGrade: "SOLID_PLAY",
+    riskLevel: "MODERATE",
+    reasoning: "Strong edge on the spread.",
+    reasoningShort: "Strong edge.",
+    factorBreakdown: {
+      consensusScore: 20,
