+
+function ctx(overrides: Partial<GameContextInput> = {}): GameContextInput {
+  return overrides;
+}
+
+function evidence(
+  category: EvidenceRecord["sourceCategory"],
+  status: EvidenceRecord["activationStatus"] = "ACTIVE"
